files.content:
@keyframes rotate {
  to {
    transform: rotate(360deg);
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  display: grid;
  place-items: center;
  inline-size: 100%;
  block-size: 100vh;
  overflow: hidden;
  background-color: #daecf9;
  background-image: url(../images/forest.png);
  background-repeat: no-repeat;
  background-position: bottom center;
  background-size: contain;
}

.helicopter {
  position: relative;
  transform: translate3d(-200px, -100px, 0);
}

.cockpit {
  position: absolute;
  z-index: 1;
  inline-size: 200px;
  block-size: 160px;
  border-radius: 100px 40px 50px 50px;
  overflow: hidden;
  background-color: #80d994;
}

.cockpit::after {
  content: '';
  position: absolute;
  inset: -40px 0 0 -60px;
  z-index: 1;
  inline-size: 170px;
  block-size: 140px;
  border-radius: 40px;
  background-color: #8d8d8d;
}

.tail {
  position: absolute;
  inset: 50px 0 0 150px;
  block-size: 10px;
  border-inline-start: 350px solid #a6deb3;
  border-block-start: 10px solid transparent;
  border-block-end: 80px solid transparent;
  transform-origin: left center;
}

.under {
  position: absolute;
  inset: -10px 0 0 130px;
  inline-size: 40px;
  block-size: 20px;
  background-color: #3d3d3e;
}

.propeller {
  position: absolute;
  inset: -320px 0 0 -150px;
  z-index: 2;
  inline-size: 600px;
  block-size: 600px;
  border-radius: 50%;
  opacity: 0.2;
  overflow: hidden;
  background-color: #939bab;
  transform: rotateX(86deg);
}

.hightlight {
  position: absolute;
  inline-size: 100%;
  block-size: 100%;
  border-radius: 50%;
  animation: rotate 0.8s linear infinite;
}

.hightlight div {
  position: absolute;
  inset: 50% 0 0 50%;
  inline-size: 700px;
  block-size: 60px;
  margin-inline-start: -350px;
  margin-block-start: -30px;
  background-color: #fff;
}

.hightlight div:nth-child(1) {
  transform: rotate(0deg);
}

.hightlight div:nth-child(2) {
  transform: rotate(90deg);
}

.propeller-back {
  position: absolute;
  inset: -75px 0 0 -65px;
  z-index: 2;
  inline-size: 140px;
  block-size: 140px;
  border-radius: 50%;
  opacity: 0.2;
  overflow: hidden;
  background-color: #939bab;
  animation: rotate 0.8s linear infinite;
}

.hightlight-back div {
  position: absolute;
  inset: 48% 0 0 -10px;
  inline-size: 160px;
  block-size: 10px;
  background-color: #fff;
}

.hightlight-back div:nth-child(1) {
  transform: rotate(40deg);
}

.hightlight-back div:nth-child(2) {
  transform: rotate(-40deg);
}

@media (width <= 786px) {
  .helicopter {
    transform: translate3d(-100px, 0, 0);
  }
}
